function card(j){const show=floorNumbers(),initials=j.operators.split(' ').map(s=>s[0]).slice(0,2).join(''),left=Math.max(0,j.goal-j.end),gap=j.end-j.goal;return `<article class="job-card"><div class="card-body"><div class="card-top"><span class="job-id">${esc(j.job)}</span>${statusPill(j,show)}</div><h3>${esc(j.cell)}</h3><div class="job-meta">Shift ${esc(j.shift)}${j.hand?' <span>·</span> '+esc(j.hand):''} <span>·</span> ${esc(j.part)}${j.overtimeMinutes?' <span>·</span> OT '+j.overtimeMinutes/60+'h':''}</div><div class="operator"><span class="operator-avatar">${esc(initials)}</span>${esc(j.operators)}</div>${stepList(j)}<p class="contribution">${contribution(j,show)}</p><p class="grades-line card-grades">${show?gradesText(j):shiftColour(j)}</p><div class="goal-strip"><span>${icon('target')}SHIFT TARGET</span><strong>${j.goal===j.start?'No full step planned':left?`${left} step${left===1?'':'s'} to goal`:'Shift goal achieved'}${show?` · ${fmtHours(earnedMinutes(j)/60)} / ${fmtHours(buildMinutes(j)/60)} h`:''}</strong></div><div class="card-note">${icon('comment')}<span>${esc(j.comment||'No shift notes yet.')}</span></div></div><div class="card-footer"><span>${show?`Shift gap ${gap>0?'+':''}${gap} step${Math.abs(gap)===1?'':'s'}`:''}</span><button class="text-button" data-next-unit="${esc(j.id)}">Next unit this shift</button><button class="text-button" data-remove="${esc(j.id)}">Remove</button><button class="text-button" data-handoff="${esc(j.id)}">Next shift</button><button class="text-button" data-trace="${esc(j.id)}">History</button><button class="text-button" data-edit="${esc(j.id)}" aria-label="Update ${esc(j.job)}">Update job ${icon('arrow')}</button></div></article>`;}
function renderSidebar(jobs){jobs=QuestProduction.latestUnits(jobs);const s=statValues(jobs),hours=jobs.reduce((sum,j)=>{try{const p=QuestEngine.progress(j);return [sum[0]+p.completedMinutes,sum[1]+p.totalMinutes];}catch{return sum;}},[0,0]);return `<aside class="side-panel" aria-label="Assembly completion"><h2>Assembly completion</h2><div class="completion-card"><div class="completion-header"><span class="overline">AVERAGE COMPLETION</span>${icon('chart')}</div><div class="completion-total">${s.average}<small>%</small></div><div class="completion-caption">${s.count} distinct job${s.count===1?'':'s'} · latest selected shift</div><div class="target-comparison"><span>Target <strong>${s.target}%</strong></span><span>Gap <strong>${s.average-s.target>0?'+':''}${s.average-s.target} pp</strong></span></div><div class="overall-progress"><span style="width:${s.average}%"></span></div><div class="completion-bottom"><span>Standard hours</span><strong>${fmtHours(hours[0]/60)} / ${fmtHours(hours[1]/60)} h</strong></div></div><div class="assembly-list">${jobs.length?jobs.map(j=>`<div class="assembly-row"><div class="assembly-label"><strong>${esc(j.job)}</strong><span>${percent(j)}%</span></div><small>${esc(j.cell)} · ${esc(j.part)}</small><div class="progress-bar" role="progressbar" aria-label="${esc(j.job)} assembly completion" aria-valuenow="${percent(j)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${percent(j)}%"></span></div></div>`).join(''):'<p class="form-hint">No jobs in this view.</p>'}</div><div class="handoff-note"><h3>${icon('comment')} A better shift handoff</h3><p>Leave a stop step and a short note so the next shift knows where to pick up.</p></div></aside>`;}
function ratingKey(){const p=state.processes.find(p=>p.id===selectedProcess),b=p.productiveMinutes/60,r=p.rating;return `<div class="rating-key"><span>Full-shift assignments · standard hours earned (${fmtBand(b)} h shift):</span><span class="rating red">Red &lt; ${fmtBand(b-r.yellowWithin)}</span><span class="rating yellow">Yellow ${fmtBand(b-r.yellowWithin)}–${fmtBand(b-r.greenWithin)}</span><span class="rating green">Green ${fmtBand(b-r.greenWithin)}–${fmtBand(b+r.purpleAbove)}</span><span class="rating purple">Purple ≥ ${fmtBand(b+r.purpleAbove)}</span><span class="rating training">Training · not rated</span></div>`;}
function renderDayBoard(jobs){$('#page-content').innerHTML=`<div class="daily-board"><section><div class="section-top"><h2>${view==='week'?'This week':'Shift assignments'} <span class="count-pill">${jobs.length}</span></h2><div class="legend"><span><i></i>In progress</span><span><i class="amber"></i>At risk</span><span><i class="red"></i>Blocked</span></div></div>${ratingKey()}<p class="form-hint">Partial-shift allocations use their own goals and appear in Operator day; they are excluded from colour comparisons until split-shift rating rules are agreed.</p><div class="job-grid">${jobs.map(card).join('')||'<div class="empty-state"><h3>A fresh board.</h3><p>No jobs match this date, shift, and work cell. Add an assignment or choose another view.</p><button class="button" data-action="today">Return to today</button></div>'}</div></section></div>`;}
function renderBase(){const titles={board:'Production board',history:'Shift history',insights:'Production insights',supervisor:'Supervisor review',process:'Process setup',architecture:'System architecture',operators:'Operator day',removed:'Removed jobs',alerts:'Station alerts'};$('#page-title').innerHTML=`${titles[page]}<span class="title-dot"></span>`;$('#breadcrumb-page').textContent=titles[page];$$('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');});$$('[data-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.view===view);b.setAttribute('aria-pressed',String(b.dataset.view===view));});$('#board-date').value=selectedDate;const jobs=filteredJobs();renderMetrics(jobs);if(page==='architecture')renderArchitecture();else if(page==='alerts')renderAlerts();else if(page==='operators')renderOperators();else if(page==='removed')renderRemoved();else if(page==='process')renderProcess();else if(page==='supervisor')renderSupervisor();else if(page==='history')renderHistory(jobs);else if(page==='insights')renderInsights(jobs);else if(tv){if(tvLayout==='cells')renderTvCells();else if(tvLayout==='timeline')renderTvTimeline();else renderTv(jobs);}else if(view==='week')renderWeek();else renderDayBoard(jobs);$('#record-count').textContent=`${jobs.length} job${jobs.length===1?'':'s'} in this view`;hydrateIcons();}
function notify(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('visible'),3500);}
const dateStep=()=>page==='operators'||page==='alerts'||tv?1:view==='week'||page==='supervisor'?7:1;
$('#shift-filter').addEventListener('change',e=>{selectedShift=e.target.value;render();});$('#cell-filter').addEventListener('change',e=>{selectedCell=e.target.value;render();});$('#board-date').addEventListener('change',e=>{if(e.target.value){selectedDate=e.target.value;render();}});$('#prev-date').onclick=()=>{selectedDate=shiftDate(selectedDate,-dateStep());render();};$('#next-date').onclick=()=>{selectedDate=shiftDate(selectedDate,dateStep());render();};
document.addEventListener('click',e=>{if(e.target.closest('.brand')){page='board';render();}const v=e.target.closest('[data-view]');if(v){view=v.dataset.view;render();}const n=e.target.closest('[data-page]');if(n){page=n.dataset.page;render();window.scrollTo(0,0);}if(e.target.closest('[data-action="today"]')){selectedDate=today;render();}});

function shortDate(d,options={month:'short',day:'numeric'}){return dateFrom(d).toLocaleDateString('en-US',options);}
// Floor view: each job's latest record through the day. A unit leaves the grid after the day it reaches its final step.
function floorUnits(date){return QuestProduction.latestUnits(activeJobs().filter(j=>j.processId===selectedProcess),date).filter(j=>j.end<j.total||j.date===date);}
// The cells in use on the line (30 for now), plus any later cell still holding a unit on this day.
const lineCells=(date=selectedDate)=>QuestProduction.cellsInUse(state.display.cellCount,floorUnits(date).map(j=>j.cell));
const shadeOf=j=>{const done=percent(j);return done===100?4:Math.min(3,Math.floor(done/25));};
function renderCellChoices(){const cells=QuestProduction.cellsInUse(state.display.cellCount,activeJobs().map(j=>j.cell));if(!cells.includes(selectedCell))selectedCell='all';$('#cell-filter').innerHTML='<option value="all">All work cells</option>'+cells.map(c=>`<option ${c===selectedCell?'selected':''}>${c}</option>`).join('');}
function renderAssemblyMetrics(){const units=floorUnits(selectedDate),complete=units.filter(j=>j.end===j.total).length,active=new Set(units.map(j=>j.cell)).size;$('#metrics').innerHTML=[['Units on the floor',units.length,'Each job counted once'],['Final step reached',complete,'Completed on this day'],['Cells with records',`${active}<small>/ ${lineCells(selectedDate).length}</small>`,'Latest records through selected day'],['Mean completion',units.length?`${Math.round(units.reduce((a,j)=>a+percent(j),0)/units.length)}<small>%</small>`:'—','Standard hours · not quality acceptance']].map(([label,value,note])=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-foot">${note}</div></div>`).join('');}
function unitTile(j){const pct=percent(j),band=shadeOf(j),stop=stepInfo(j).stop;return `<div class="unit-tile shade-${band}"><button class="unit-main" data-trace="${esc(j.id)}" aria-label="${esc(j.job)}: ${pct}% complete. Open shift history"><span>${esc(j.job)}${j.hand?' · '+esc(j.hand):''}</span><strong>${pct}%</strong><small>${j.end?`Stop ${j.end} · ${esc(namesOf(j)[j.end-1])}`:esc(stop.name)}</small><small>${shortDate(j.date)} · Shift ${esc(j.shift)} · ${esc(j.operators)}</small></button>${j.end<j.total?`<button class="unit-action" data-handoff="${esc(j.id)}">Assign next shift ${icon('arrow')}</button>`:'<span class="unit-done">Final step recorded</span>'}<div class="unit-tools"><button data-edit="${esc(j.id)}">Edit</button><button data-remove="${esc(j.id)}">Remove</button><button data-next-unit="${esc(j.id)}">Next unit</button></div></div>`;}
function renderWeek(){
 const units=floorUnits(selectedDate),alerts=alertsByCell(selectedDate),cells=lineCells(selectedDate),timeline=cellsMode==='timeline';
 $('#page-content').innerHTML=`<div class="section-top"><h2>Week of ${shortDate(weekDates()[0])}</h2><span class="secondary-text">All shifts · assembly progress</span></div><div class="assembly-week">${weekDates().map(d=>{const records=floorUnits(d);return `<button class="assembly-day ${d===selectedDate?'selected':''}" data-assembly-day="${d}" aria-pressed="${d===selectedDate}"><span>${shortDate(d,{weekday:'short'})}</span><strong>${shortDate(d,{day:'numeric'})}</strong><small>${d>today?'Upcoming':`${records.length} on the floor`}</small></button>`;}).join('')}</div><div class="section-top cell-grid-heading"><div><h2>${shortDate(selectedDate,{weekday:'long',month:'long',day:'numeric'})} · ${cells.length} cells</h2><p class="form-hint">${timeline?'Where each cell\'s unit sits in its route, by standard hours. Select a cell for the unit\'s shift history.':'Latest recorded progress through this day. Assign a cell to start a job, or hand a unit to the next shift.'}</p></div>${cellsModeToggle()}</div>${timeline?lineTimeline(selectedDate):`<div class="completion-legend grid-legend"><span>0%</span><i></i><span>100% complete</span></div><div class="assembly-cells">${cells.map(cell=>{const rows=units.filter(j=>j.cell===cell);const alert=alerts.get(cell);return `<section class="assembly-cell ${rows.length?'':'empty-cell'} ${alert&&!alert.acknowledged?'alert-'+alert.level:''}"><div class="cell-top"><h3>${cell}</h3>${alertChip(alert)}${rows.length?`<button class="text-button" data-cell-day="${cell}">Daily goals ${icon('right')}</button>`:'<span>No record</span>'}</div>${rows.map(unitTile).join('')}<button class="assign-button" data-assign-cell="${cell}" aria-label="Assign a new job to ${cell}">${icon('plus')}${rows.length?'Add job':'Assign job'}</button></section>`;}).join('')}</div><p class="form-hint">Darker green means more of the unit's standard hours are complete. A unit stays on the grid through the day it reaches its final step. Empty cells are unknown, not 0%. Cells 01–${String(state.display.cellCount).padStart(2,'0')} are in use (Process setup → Floor display); the labels are placeholders until the cell roster is confirmed. Select a unit for its shift history.</p>`}`;
}
function continueShift(id){
 const source=activeJobs().find(j=>j.id===id);if(!source||tv)return;
 const latest=QuestProduction.latestUnits(activeJobs().filter(j=>QuestProduction.unitKey(j)===QuestProduction.unitKey(source)))[0];
 if(latest.id!==source.id){notify('Use Next shift on the latest assignment for this job.');return;}
 if(source.end===source.total){notify('This job has reached its final step.');return;}
 const draft=QuestProduction.nextShift(source);
 if(activeJobs().some(j=>QuestProduction.unitKey(j)===QuestProduction.unitKey(source)&&j.date===draft.date&&j.shift===draft.shift)){notify('An assignment already exists for the next shift.');return;}
 draft.productiveMinutes=state.processes.find(p=>p.id===source.processId).productiveMinutes;
 openJob(null,draft);
}
function assignCell(cell){openJob(null,null,{cell,date:selectedDate});}
function showTrace(id){
 const source=activeJobs().find(j=>j.id===id);if(!source||tv)return;
 const rows=activeJobs().filter(j=>QuestProduction.unitKey(j)===QuestProduction.unitKey(source)).sort(QuestProduction.compare);
 $('#trace-content').innerHTML=`<div class="dialog-heading"><div><span class="eyebrow">UNIT HISTORY · EVERY RECORDED SHIFT</span><h2 id="trace-title">${esc(source.job)}</h2><p>${esc(source.part)} · ${esc(source.cell)} · ${percent(rows.at(-1))}% complete</p></div></div>${unitSummary(rows)}<div class="trace-list">${rows.map(j=>{const s=stepInfo(j);return `<article><div><strong>${shortDate(j.date)} · Shift ${esc(j.shift)}</strong>${statusPill(j)}</div><h3>${esc(j.operators)}</h3><p class="contribution">${contribution(j)}</p><p>${observedTime(j)}</p><p class="grades-line">${gradesText(j)}</p><p>${esc(j.cell)} · Start ${esc(stepText(s.start))} → Stop ${esc(stepText(s.stop))}</p><p>Goal ${esc(stepText(s.goal))} · ${fmtHours(earnedMinutes(j)/60)} of ${fmtHours(buildMinutes(j)/60)} h to build</p><p>${esc(j.comment||'No comment recorded.')}</p><button class="text-button" data-trace-edit="${esc(j.id)}">Review this shift</button></article>`;}).join('')}</div><p class="form-hint">One assignment per job, date, and shift. Completion is cumulative; the percentage-point gain belongs to this assignment. Shift history retains before/after corrections. Gaps between recorded steps are not credited to an operator. Hands-on and waiting time are lead-entered person-hours; the time study is the standard they are compared with.</p>`;
 $('#trace-dialog').showModal();
}
document.addEventListener('click',e=>{
 const day=e.target.closest('[data-assembly-day]');if(day){selectedDate=day.dataset.assemblyDay;render();}
 const cell=e.target.closest('[data-cell-day]');if(cell){selectedCell=cell.dataset.cellDay;selectedShift='all';view='day';$('#cell-filter').value=selectedCell;$('#shift-filter').value='all';render();}
 const assign=e.target.closest('[data-assign-cell]');if(assign)assignCell(assign.dataset.assignCell);
 const handoff=e.target.closest('[data-handoff]');if(handoff)continueShift(handoff.dataset.handoff);
 const trace=e.target.closest('[data-trace]');if(trace)showTrace(trace.dataset.trace);
 const edit=e.target.closest('[data-trace-edit]');if(edit){$('#trace-dialog').close();openJob(edit.dataset.traceEdit);}
});
function historyRows(){const dates=view==='week'?weekDates():[selectedDate];return state.history.filter(h=>h.processId===selectedProcess&&dates.includes(h.date)&&(selectedShift==='all'||h.shift===selectedShift)&&(selectedCell==='all'||h.cell===selectedCell)).sort((a,b)=>b.at.localeCompare(a.at));}
const historyJob=h=>({...h,end:h.to,start:h.start??h.from});
function historyStatus(h){return statusOf(historyJob(h));}
function renderHistory(){const rows=historyRows();$('#page-content').innerHTML=`<div class="section-top"><h2>Shift activity <span class="count-pill">${rows.length}</span></h2><button class="button" id="export-history">${icon('download')}Export CSV</button></div><div class="history-panel">${rows.length?rows.map(h=>{const j=historyJob(h),s=stepInfo(j);return `<article class="history-row"><div class="history-symbol">${icon(h.kind==='Job added'?'plus':'history')}</div><div class="history-detail"><div class="history-title"><strong>${esc(h.job)}</strong><span>${esc(h.kind)}</span>${statusPill(j)}</div><p>${esc(h.part)} · ${esc(h.cell)} · Shift ${esc(h.shift)} · ${esc(h.operators)}</p><div class="history-steps">Start ${esc(h.startName||stepText(s.start))} ${icon('arrow')} <strong>Stop ${esc(h.stopName||stepText(s.stop))}</strong><span>Goal ${esc(h.goalName||stepText(s.goal))} · Gap ${h.gap>0?'+':''}${h.gap} · OT ${h.overtimeMinutes/60}h · ${fmtHours(earnedMinutes(j)/60)} h earned</span></div><p>${observedTime(h)}</p><p class="history-note">${esc(h.comment||'No comment recorded.')}</p></div><time datetime="${esc(h.at)}">${shortDate(h.date)}<small>${new Date(h.at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}</small></time></article>`;}).join(''):'<div class="empty-state"><h3>No shift activity yet.</h3><p>Updates for this date, shift, and work cell will appear here.</p></div>'}</div><p class="form-hint">Sample records are labeled. Each update keeps a snapshot of the step names, goal, stop, hours earned, colour, and note on this device.</p>`;}
function renderInsights(jobs){const dates=view==='week'?weekDates():[selectedDate];const cells=[...new Set(jobs.map(j=>j.cell))].filter(c=>selectedCell==='all'||c===selectedCell);$('#page-content').innerHTML=`<div class="insights-grid">${flowInsights(jobs)}<section class="insight-card"><div class="section-top"><h2>Goals reached by day</h2><span class="secondary-text">${view==='week'?'Selected week':'Selected day'}</span></div><div class="goal-chart">${dates.map(d=>{const rows=jobs.filter(j=>j.date===d&&j.goal>j.start),met=rows.filter(j=>j.end>=j.goal).length,pct=rows.length?Math.round(met/rows.length*100):0;return `<div class="chart-column"><strong>${rows.length?pct+'%':'—'}</strong><div class="chart-track"><div style="height:${pct}%"></div></div><span>${shortDate(d,{weekday:'short'})}</span><small>${met} / ${rows.length}</small></div>`;}).join('')}</div><p class="form-hint">Assignments at or beyond their saved goal step. This measures goal attainment, not labor productivity.</p></section><section class="insight-card"><h2>Work-cell overview</h2><div class="cell-insights">${cells.map(cell=>{const rows=jobs.filter(j=>j.cell===cell),s=statValues(QuestProduction.latestUnits(rows));return `<div class="cell-insight"><div><strong>${cell}</strong><span>${s.count} distinct jobs</span></div><div class="cell-percentage">${s.average}%<small>avg. completion</small></div><div class="progress-bar"><span style="width:${s.average}%"></span></div><p><span>${s.met} goals met</span><span>${s.attention} need attention</span></p></div>`;}).join('')}</div></section><section class="insight-card attention-insight"><h2>Items to follow up</h2>${jobs.filter(j=>ATTENTION.includes(statusOf(j))).map(j=>`<button class="attention-row" data-edit="${esc(j.id)}">${statusPill(j)}<div><strong>${esc(j.job)} · ${esc(j.cell)} · ${shortDate(j.date)} · Shift ${esc(j.shift)}</strong><p>${esc(j.comment||'No reason recorded.')}</p></div>${icon('right')}</button>`).join('')||'<p class="form-hint">No reported blockers, at-risk jobs, or red finished shifts in this view.</p>'}</section></div>`;}
function tvPageSize(){return Math.max(1,Math.min(window.innerWidth>=1600?6:3,Math.floor((window.innerHeight-405)/(window.innerWidth>=1600?125:105))));}
const tvStep=(step,cls='')=>`<td class="tv-step ${cls}"><strong>${step.k??'–'}</strong><small>${esc(step.name)}</small></td>`;
function renderTv(jobs){const show=floorNumbers(),size=tvPageSize(),pages=Math.max(1,Math.ceil(jobs.length/size));tvPage%=pages;const visible=jobs.slice(tvPage*size,tvPage*size+size);$('#page-content').innerHTML=tvControls()+alertStrip()+`<div class="tv-board-layout"><section><div class="section-top"><h2>${shortDate(selectedDate,{weekday:'long',month:'long',day:'numeric'})} <span class="count-pill">${selectedShift==='all'?'All shifts':'Shift '+selectedShift}</span></h2><span class="tv-pagination">${pages>1?`Page ${tvPage+1} / ${pages} · ${tvPaused?'Paused':state.display.rotateSeconds+' s'}`:'Shift assignments'}</span></div><div class="tv-table-scroll"><table class="tv-table"><thead><tr><th>Job / work cell</th><th>Operator(s)</th><th>Start</th><th>Goal</th><th>Stop</th>${show?'<th>Gap</th><th>Hours</th><th>Status</th>':'<th>Result</th>'}</tr></thead><tbody>${visible.map(j=>{const s=stepInfo(j),rating=ratingOf(j);return `<tr><td><strong>${esc(j.job)}</strong><small>${esc(j.cell)}${j.hand?' · '+esc(j.hand):''}</small></td><td class="tv-person"><span>${esc(j.operators)}</span>${j.overtimeMinutes?`<small>+${j.overtimeMinutes/60} h overtime</small>`:''}</td>${tvStep(s.start)}${tvStep(s.goal,'tv-goal')}${tvStep(s.stop,'tv-actual')}${show?`<td class="tv-gap ${j.end<j.goal?'negative':''}">${j.end>j.goal?'+':''}${j.end-j.goal}</td><td class="tv-hours ${rating?'band-'+rating:''}">${fmtHours(earnedMinutes(j)/60)}<small>of ${fmtHours(buildMinutes(j)/60)} h</small></td>`:''}<td class="${show?'':'tv-result '+(rating?'band-'+rating:'')}">${statusPill(j,show)}</td></tr>`;}).join('')||`<tr><td colspan="${show?8:6}">No assignments in this view.</td></tr>`}</tbody></table></div><div class="tv-key"><span>Start = first step this shift</span><span>Goal = expected last step by shift end</span><span>Stop = last step completed</span>${show?'<span>Gap = stop − goal, in steps</span><span>Hours = standard hours earned; finished shifts use the workbook colours</span>':'<span>Result = the finished shift\'s workbook colour; leads and supervisors see the hours</span>'}</div></section>${renderSidebar(jobs)}</div>`;}
function render(){renderBase();const assembly=page==='board'&&((view==='week'&&!tv)||(tv&&tvLayout!=='goals')),supervisor=page==='supervisor';$('#shift-filter').disabled=assembly||page==='operators';$('#cell-filter').disabled=assembly||page==='operators';$('#process-filter').disabled=page==='operators';$('#record-count').textContent=assembly?`${lineCells(selectedDate).length} cells in use · all shifts · latest recorded progress`:supervisor?'All processes, cells, and shifts · finished shifts only':$('#record-count').textContent;if(assembly)$('#page-title').textContent='Assembly progress';$$("[data-view]").forEach(b=>b.textContent=page==="board"?(b.dataset.view==="day"?"Daily goals":"Weekly assemblies"):(b.dataset.view==="day"?"Day view":"Week view"));const subtitles={board:view==='week'?'A320 lofting · Step 1: hand layup. Choose a day to review all cells, or a cell to assign it.':'Daily operator goals · review each shift independently.',history:'Every update, ready for the next handoff.',insights:'Separate the person from the unit. Find where units lose time.',supervisor:'Shift colours by operator. A flag starts a conversation, not a verdict.',process:'A reusable board, driven by a named route.',architecture:'Current architecture hypothesis — subject to stakeholder validation.',operators:'Each person\'s day, standard hours plus overtime, booked across every unit, cell and shift.',alerts:'Stations that are blocked, at risk, or losing process time to waiting. A prompt to check in, not a verdict.',removed:'Recover mistaken removals. Previous updates stay in history.'};$('#page-subtitle').textContent=subtitles[page];$('#add-job').hidden=tv||page!=='board';$('#tv-toggle').hidden=page!=='board';$('.view-toggle').hidden=tv||supervisor||page==='operators'||page==='alerts';$('.filters').hidden=supervisor||page==='alerts';const auxiliary=['process','architecture','removed'].includes(page);$('#metrics').hidden=auxiliary||supervisor||page==='operators'||page==='alerts'||tv;$('.board-toolbar').hidden=auxiliary;$('.page-footer').hidden=auxiliary;$('.eyebrow').textContent=supervisor?'ALL PROCESSES':state.processes.find(p=>p.id===selectedProcess)?.name.toUpperCase()||'QUEST';const weekly=(view==='week'&&!['operators','alerts'].includes(page)&&!tv)||supervisor;$('#prev-date').setAttribute('aria-label',weekly?'Previous week':'Previous day');$('#next-date').setAttribute('aria-label',weekly?'Next week':'Next day');updateAlertBell();if(tv)$('#page-title').textContent=state.processes.find(p=>p.id===selectedProcess).name+' · Production';document.title=`${tv?'TV display':{board:'Production board',history:'Shift history',insights:'Insights',supervisor:'Supervisor review',process:'Process setup',architecture:'System architecture',operators:'Operator day',removed:'Removed jobs',alerts:'Station alerts'}[page]} · QUEST`;}
function startOptions(names,start){return names.map((name,i)=>`<option value="${i}" ${i===start?'selected':''}>${i+1} · ${esc(name)}</option>`).join('')+(start>=names.length?`<option value="${names.length}" selected>Unit complete · no steps left</option>`:'');}
function stopOptions(names,start,end){return `<option value="${start}" ${end===start?'selected':''}>No step completed this shift</option>`+names.slice(start).map((name,i)=>`<option value="${start+i+1}" ${start+i+1===end?'selected':''}>${start+i+1} · ${esc(name)}</option>`).join('');}
