// Hours to build = regular + additional − waiting; the goal is set from these.
function formHours(f){const regular=Number(f.elements.allocationHours.value)*60,extra=QuestProduction.overtimeMinutes(f.elements.overtimeHours.value),wait=f.elements.delayHours.value===''?0:Number(f.elements.delayHours.value)*60;return {regular,extra,wait,build:Math.max(0,regular+extra-wait)};}
function hoursSum(h){return `${fmtHours(h.regular/60)} h regular${h.extra?` + ${fmtHours(h.extra/60)} h additional`:''}${h.wait?` − ${fmtHours(h.wait/60)} h waiting`:''} = ${fmtHours(h.build/60)} h to build`;}
// What the selected stop means: person grade on the hours to build, process efficiency on the total hours.
function stopGrades(f){const h=formHours(f),seq=window.questEditingSequence,start=Number(f.elements.start.value),end=Number(f.elements.end.value);if(!(end>start))return '';let earned;try{earned=QuestEngine.progress({start,end,stepMinutes:seq.stepMinutes,rateMultiplier:seq.rateMultiplier}).earnedMinutes;}catch{return '';}const worked=h.regular+h.extra;return `At this stop: person grade ${pct(h.build>0?earned/h.build:null)} · process ${pct(worked>0?1-Math.min(h.wait,worked)/worked:null)}<br>`;}
function editorGoal(){const f=$('#job-form'),seq=window.questEditingSequence;return QuestEngine.calculateGoal({start:Number(f.elements.start.value),stepMinutes:seq.stepMinutes,productiveMinutes:formHours(f).build,rateMultiplier:seq.rateMultiplier,rule:seq.goalRule});}
function updateGoalPreview(){updateAllocationNote();const f=$('#job-form'),seq=window.questEditingSequence;try{const result=editorGoal(),named=result.goal>Number(f.elements.start.value);$('#goal-preview').innerHTML=`<div><span>CALCULATED SHIFT GOAL</span><strong>${named?`Step ${result.goal}`:'No full step'} <small>/ ${result.total}</small></strong><em>${esc(named?seq.stepNames[result.goal-1]:'The next step does not fit this budget')}</em></div><p><b>${hoursSum(formHours(f))}</b><br>${fmtHours(result.usedMinutes/60)} h of standard work planned.<br>${stopGrades(f)}${seq.goalRule==='nearest'?'Nearest step to the budget, as in the current workbook.':'Only whole steps that fit the budget count.'}</p>`;$('#goal-preview').dataset.goal=String(result.goal);}catch(error){$('#goal-preview').innerHTML=`<p>${esc(error.message)}</p>`;}}
function validateJob(j){const timeError=timeValidation(j);if(timeError)return timeError;if(!j.job.trim()||!j.part.trim()||!j.operators.trim())return 'Add a name and a job number.';if(!/^\d{4}-\d{2}-\d{2}$/.test(j.date)||!Number.isFinite(dateFrom(j.date).getTime())||isoDate(dateFrom(j.date))!==j.date)return 'Choose a valid assignment date.';if(!QuestProduction.shifts.includes(j.shift)||!CELL_NAMES.includes(j.cell)||!['on-track','at-risk','blocked'].includes(j.status))return 'Choose valid shift, work-cell, and status options.';if(![j.start,j.end,j.goal,j.total].every(n=>Number.isInteger(n)&&n>=0&&n<=999)||j.total<1)return 'Steps must be whole numbers; total steps must be at least 1.';if(j.end<j.start)return 'The stop step cannot be before the start step.';if(j.goal<j.start)return 'The shift goal cannot be before the start step.';if(Math.max(j.start,j.end,j.goal)>j.total)return 'Start, stop, and goal steps cannot exceed the route.';if(handoffSource){const source=activeJobs().find(old=>old.id===handoffSource);if(!source||QuestProduction.compare({...j,updatedAt:source.updatedAt},source)<=0)return "Choose a shift after the previous assignment.";}if(activeJobs().some(other=>other.id!==j.id&&(QuestProduction.unitKey(other)===QuestProduction.unitKey(j)||(other.processId===j.processId&&other.job.toLowerCase()===j.job.toLowerCase()))&&other.date===j.date&&other.shift===j.shift))return 'This job already has an assignment for the same date and shift.';return validateContinuity(j);}
