function exportHistory(){const fields=['Assignment date','Shift','Cell','Job','Assembly','Update type','Previous step','End step','Goal','Total steps','Status','Operator(s)','Start step','Gap','Productive minutes','Overtime minutes','Shift finished','Process','Timing revision','Comment','Recorded at','Assignment ID','Previous assignment ID','Hand','Overtime hours','Start step name','Stop step name','Goal step name','Standard hours earned','Shift budget hours','Shift colour','Training shift','Goal rule','Unit ID','Person day hours (standard + overtime)','Hours to build','Waiting hours','Waiting reason'];const rows=historyRows().map(h=>{const j=historyJob(h),s=stepInfo(j),earned=Number.isFinite(h.earnedMinutes)?h.earnedMinutes:earnedMinutes(j);return [h.date,h.shift,h.cell,h.job,h.part,h.kind,h.from,h.to,h.goal,h.total,statusNames[historyStatus(h)],h.operators,h.start,h.gap,h.productiveMinutes,h.overtimeMinutes,h.closed,h.processId,h.configRevision,h.comment,h.at,h.assignmentId,h.previousAssignmentId,h.hand,h.overtimeMinutes/60,h.startName||stepText(s.start),h.stopName||stepText(s.stop),h.goalName||stepText(s.goal),Number.isFinite(earned)?Math.round(earned/6)/10:'',budgetMinutes(h)/60,ratingOf(j)||'',!!h.training,h.goalRule||'whole',h.unitId,h.shiftCapacityMinutes==null?'':h.shiftCapacityMinutes/60,QuestTracking.hours(h).buildMinutes/60,h.delayMinutes==null?'':h.delayMinutes/60,h.delayReason];});const blob=new Blob(['﻿'+[fields,...rows].map(r=>r.map(QuestStorage.csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`quest-shift-history-${selectedDate}.csv`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Shift history exported');}
