if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_production_board',title:'Read the production board',description:'Read fictional demo assignments in the current date, shift, and work-cell view, with start, goal, and stop step names.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('No input fields are accepted.');const assembly=page==="board"&&view==="week"&&!tv;const jobs=assembly?floorUnits(selectedDate):filteredJobs();return {date:selectedDate,view,shift:assembly?"all":selectedShift,cell:assembly?"all":selectedCell,jobs:jobs.map(j=>{const s=stepInfo(j);return {id:j.id,job:j.job,part:j.part,cell:j.cell,start:j.start,end:j.end,goal:j.goal,startStep:stepText(s.start),goalStep:stepText(s.goal),stopStep:stepText(s.stop),completion:percent(j),status:statusOf(j)};}),summary:statValues(jobs)};}});register({name:'start_job_update',title:'Open a job update',description:'Open the supervisor form for a demo assignment. Does not save changes; the user can review and save in the form.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='id')||typeof input.id!=='string'||!activeJobs().some(j=>j.id===input.id))throw new Error('Unknown assignment.');if(tv)throw new Error('Exit TV display before opening an update.');openJob(input.id);return {opened:true,id:input.id,saved:false};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

function renderSupervisor(){const end=weekDates()[6],first=shiftDate(weekDates()[0],-7*(supervisorWeeks-1)),finished=activeJobs().filter(j=>j.closed&&j.date>=first&&j.date<=end),rated=finished.map(j=>({j,rating:ratingOf(j)})).filter(r=>r.rating),people=QuestProduction.operatorSummary(rated.map(({j,rating})=>({operators:j.operators,rating,earnedMinutes:earnedMinutes(j),budgetMinutes:buildMinutes(j)}))),flagged=p=>p.purple>=flagAt||p.red>=flagAt,skipped=finished.length-rated.length,purples=rated.filter(r=>r.rating==='purple').map(r=>r.j).sort(QuestProduction.compare).reverse();people.sort((a,b)=>flagged(b)-flagged(a)||b.purple-a.purple||b.red-a.red||a.name.localeCompare(b.name));
 $('#page-content').innerHTML=`<div class="supervisor-banner"><span class="hypothesis-badge">SUPERVISOR REVIEW · DEMO</span><p>No login protects this page in the prototype. Confirm with union and workforce leads which comparisons are allowed before real names are used.</p></div><div class="section-top supervisor-top"><h2>${shortDate(first)} – ${shortDate(end)} <span class="count-pill">${rated.length} rated assignments</span></h2><div class="supervisor-controls"><label>Range <select id="supervisor-weeks">${[[1,'Selected week'],[2,'Last 2 weeks'],[4,'Last 4 weeks']].map(([w,l])=>`<option value="${w}" ${w===supervisorWeeks?'selected':''}>${l}</option>`).join('')}</select></label><label>Flag at <select id="flag-at">${[2,3,4].map(n=>`<option value="${n}" ${n===flagAt?'selected':''}>${n}+ assignments</option>`).join('')}</select></label></div></div><div class="table-scroll"><table class="supervisor-table"><thead><tr><th>Operator</th><th>Rated assignments</th><th><span class="rating purple">Purple</span></th><th><span class="rating green">Green</span></th><th><span class="rating yellow">Yellow</span></th><th><span class="rating red">Red</span></th><th>Earned / hours to build</th><th>Person grade</th><th>Review flag</th></tr></thead><tbody>${people.map(p=>`<tr class="${flagged(p)?'flagged':''}"><td><strong>${esc(p.name)}</strong></td><td>${p.shifts}</td><td>${p.purple||'–'}</td><td>${p.green||'–'}</td><td>${p.yellow||'–'}</td><td>${p.red||'–'}</td><td>${fmtHours(p.earnedMinutes/60)} / ${fmtHours(p.budgetMinutes/60)} h</td><td>${pct(p.budgetMinutes>0?p.earnedMinutes/p.budgetMinutes:null)}</td><td>${[p.purple>=flagAt?`${p.purple} purple`:'',p.red>=flagAt?`${p.red} red`:''].filter(Boolean).join(' · ')||'—'}</td></tr>`).join('')||'<tr><td colspan="9">No finished, colour-rated assignments in this range.</td></tr>'}</tbody></table></div><p class="form-hint">Purple = a finished shift at or above its budget plus the purple margin (8.05 h or more on an 8 h shift, as in the workbook). Repeated purples can mean strong output or rushed work, so treat a flag as a prompt to review, not a verdict. Person grade = standard hours earned ÷ hours to build (total hours − waiting), so waiting is never held against the operator. ${skipped} finished shift${skipped===1?' is':'s are'} excluded: training, reported blockers, partial-shift allocations, or no time budget. All processes, cells, and shifts are included.</p><section class="insight-card purple-list"><div class="section-top"><h2>Purple shifts in this range <span class="count-pill">${purples.length}</span></h2></div>${purples.map(j=>{const s=stepInfo(j);return `<button class="attention-row" data-trace="${esc(j.id)}">${statusPill(j)}<div><strong>${esc(j.operators)} · ${esc(j.job)} · ${esc(j.cell)} · ${shortDate(j.date)} · Shift ${esc(j.shift)}</strong><p>Start ${esc(stepText(s.start))} → Stop ${esc(stepText(s.stop))} · ${esc(j.comment||'No comment recorded.')}</p></div>${icon('right')}</button>`;}).join('')||'<p class="form-hint">No purple shifts in this range.</p>'}</section>`;}
function renderProcess(){const p=state.processes.find(p=>p.id===selectedProcess);$('#page-content').innerHTML=`<div class="configuration-banner"><span class="status at-risk">Sample route</span><p>Fictional step names and timings. Real standard minutes come from the industrial-engineering time study: an average of observed builds across experience levels. The board displays progress against them; it does not change them. Paste the approved route below to try it on this device; nothing is uploaded or bundled.</p></div><section class="process-panel"><form id="process-form"><div class="section-top"><h2>Process configuration</h2><span class="count-pill">Revision ${p.revision}</span></div><div class="form-grid"><label class="field">Process<select id="config-process">${state.processes.map(process=>`<option value="${process.id}" ${process.id===selectedProcess?'selected':''}>${esc(process.name)}</option>`).join('')}</select></label><label class="field">Display name<input name="name" value="${esc(p.name)}" required maxlength="60"></label><label class="field">Standard shift for goals (hours)<input name="budgetHours" type="number" min="0" max="24" step="0.25" required value="${p.productiveMinutes/60}"></label><label class="field">Goal rule<select name="goalRule"><option value="nearest" ${p.goalRule==='nearest'?'selected':''}>Nearest step · current workbook</option><option value="whole" ${p.goalRule==='whole'?'selected':''}>Whole steps that fit</option></select></label><label class="field">Timing rate multiplier (1 = standard)<input name="rateMultiplier" type="number" min="0.1" max="10" step="0.1" required value="${p.rateMultiplier}"></label><label class="field">Number of steps<input id="config-step-count" type="number" min="1" max="999" step="1" value="${p.stepMinutes.length}" required></label></div><div class="rating-config"><h3>Shift colour bands</h3><p class="form-hint">Hours relative to the shift budget. The defaults reproduce the workbook on an 8 h shift: red below 6.5 h, yellow to 7.5 h, green to 8.05 h, purple at 8.05 h or more. Overtime moves every band up.</p><div class="form-grid"><label class="field">Purple at or above budget + (h)<input name="purpleAbove" type="number" min="0" max="4" step="0.01" required value="${p.rating.purpleAbove}"></label><label class="field">Green within (h below budget)<input name="greenWithin" type="number" min="0" max="8" step="0.05" required value="${p.rating.greenWithin}"></label><label class="field">Yellow within (h below budget)<input name="yellowWithin" type="number" min="0" max="8" step="0.05" required value="${p.rating.yellowWithin}"></label></div></div><div class="timing-header"><h3>Route · time-study standards</h3><span id="route-total"></span></div><div id="timing-fields" class="route-list">${p.stepNames.map((name,i)=>routeRow(i,name,p.stepMinutes[i])).join('')}</div><details class="route-import"><summary>Paste a route from a spreadsheet</summary><p class="form-hint">One step per line: the name, then minutes. Copy the name and minutes columns from Excel, or type lines like “Peel skin, 60”. The route loads into this form for review; save to apply it to new assignments.</p><textarea id="route-import" rows="6" placeholder="Step name, minutes"></textarea><button type="button" class="button" id="apply-import">Load into form</button></details><p class="form-hint">Leads choose start and stop by these names. Existing assignments and history keep their saved revision; new assignments use this one.</p><p class="form-error" id="config-error" role="alert"></p><div class="config-footer"><button type="button" class="button" id="restore-process">${icon('reset')}Restore standard route</button><button class="button primary" type="submit">Save configuration</button></div></form></section><div class="engine-explainer"><div><span class="eyebrow">GOAL ENGINE</span><h2>Start step + shift hours → goal step</h2><p>Begin after the last completed step and add the shift budget plus overtime. The nearest-step rule picks the step whose cumulative standard time is closest to that total, as the current workbook does; the whole-step rule counts only steps that fit.</p></div><div class="formula">Hours earned = standard time from start to stop<br><strong>Colour = hours earned vs. the shift budget</strong></div></div>${displayPanel()}`;updateRouteTotals();}
function routeRow(i,name,minutes){return `<div class="route-row"><span>${i+1}</span><input name="stepName" value="${esc(name)}" maxlength="120" required aria-label="Step ${i+1} name"><label><input name="duration" type="number" min="0" max="10000" step="any" value="${minutes}" required aria-label="Step ${i+1} minutes"><small>min</small></label><small class="route-cum"></small></div>`;}
function updateRouteTotals(){const form=$('#process-form');if(!form)return;let sum=0;const rows=$$('.route-row',form);rows.forEach(row=>{const n=Number($('[name="duration"]',row).value);sum+=Number.isFinite(n)&&n>0?n:0;$('.route-cum',row).textContent=`${fmtBand(sum/60)} h`;});$('#route-total').textContent=`${rows.length} steps · ${fmtHours(sum/60)} standard hours · 0 min = checkpoint`;}
function loadRoute(names,minutes){$('#config-step-count').value=names.length;$('#timing-fields').innerHTML=names.map((name,i)=>routeRow(i,name,minutes[i])).join('');updateRouteTotals();}
function saveProcess(e){e.preventDefault();const form=e.target;const p=state.processes.find(p=>p.id===selectedProcess);const next={...p,name:form.elements.name.value.trim(),productiveMinutes:Math.round(Number(form.elements.budgetHours.value)*60),rateMultiplier:Number(form.elements.rateMultiplier.value),goalRule:form.elements.goalRule.value,rating:{purpleAbove:Number(form.elements.purpleAbove.value),greenWithin:Number(form.elements.greenWithin.value),yellowWithin:Number(form.elements.yellowWithin.value)},stepNames:$$('[name="stepName"]',form).map(el=>el.value.trim()),stepMinutes:$$('[name="duration"]',form).map(el=>Number(el.value)),revision:p.revision+1};try{QuestEngine.validateTimings(next.stepMinutes);QuestEngine.validateRating(next.rating);if(next.stepNames.some(name=>!name||name.length>120))throw Error('Every step needs a name of up to 120 characters.');if(!next.name||!Number.isFinite(next.productiveMinutes)||next.productiveMinutes<0||!Number.isFinite(next.rateMultiplier)||next.rateMultiplier<=0||!['nearest','whole'].includes(next.goalRule))throw Error('Enter a name, a valid time budget, a goal rule, and a positive rate.');}catch(error){$('#config-error').textContent=error.message;return;}state.processes=state.processes.map(old=>old.id===next.id?next:old);recordRevision(next);const saved=saveState();renderProcessChoices();render();notify(saved?'Configuration saved · existing records preserved':'Configuration updated for this session only');}
function applyImport(){try{const {names,minutes}=QuestProduction.parseRoute($('#route-import').value);loadRoute(names,minutes);$('#config-error').textContent='';notify(`${names.length} steps loaded · review, then save`);}catch(error){$('#config-error').textContent=error.message;}}
// "Revert to ideal state": reload the standard route into the form. Saving it creates a new revision; older records keep theirs.
function restoreProcess(){const base=DEFAULT_PROCESSES.find(d=>d.id===selectedProcess),form=$('#process-form');if(!base){$('#config-error').textContent='This process has no standard route to restore.';return;}form.elements.name.value=base.name;form.elements.budgetHours.value=base.productiveMinutes/60;form.elements.rateMultiplier.value=base.rateMultiplier;form.elements.goalRule.value=base.goalRule;for(const key of ['purpleAbove','greenWithin','yellowWithin'])form.elements[key].value=base.rating[key];loadRoute(base.stepNames,base.stepMinutes);$('#config-error').textContent='';notify('Standard route loaded · save to apply');}
function renderProcessChoices(){$('#process-filter').innerHTML=state.processes.map(p=>`<option value="${esc(p.id)}" ${p.id===selectedProcess?'selected':''}>${esc(p.name)}</option>`).join('');}
const architectureLayers={
 input:{number:'01',name:'User input',tag:'Working in demo',icon:'plus',summary:'Lead / supervisor → controlled form',detail:'Leads pick start and stop steps by name from the route, so free text cannot break a lookup the way it can in the workbook. The form validates step order and duplicate job/date/shift assignments before anything is saved.',fields:['Date, shift, operator(s), work cell','Job ID, part / assembly, hand, process','Start and stop chosen by step name','Additional hours worked, entered by the lead','Waiting hours and reason, not held against the operator'],boundary:'Names are fictional in this demo. Permitted identity visibility and comparisons require stakeholder agreement.'},
 logic:{number:'02',name:'Goal engine',tag:'Working in demo',icon:'target',summary:'Named route → goal step, hours, colour',detail:'A pure calculation module walks the selected route from the start step. By default the goal is the step nearest to the start plus the shift budget, the same lookup the current workbook uses. Standard hours earned between start and stop set a finished shift\'s colour band.',fields:['Goal = step nearest to start + shift hours','Gap = stop − goal, in steps','Hours earned = standard time, start to stop','Red / yellow / green / purple, as in the workbook','Saved revisions preserve past calculations'],boundary:'Sample routes and thresholds only. The meaning of purple, TAC, breaks, parallel work, rework, and final acceptance remain open decisions.'},
 board:{number:'03',name:'Production board',tag:'Working in demo',icon:'board',summary:'HTML / CSS / JavaScript interface',detail:'One board engine displays records from configurable routes. Supervisors see the cells in use (30 of 36), a line timeline, daily goals, controlled editing, target gaps, and familiar colours; the floor sees colours, not individual numbers; a separate review page groups colours by operator.',fields:['Weekly grid of the cells in use; select a cell to assign','Line timeline: each unit\'s place in its route','TV: all cells at once or in sixes; colour-only results','Supervisor review of colours by operator','Colour labels remain readable without colour','No direct SAP or ERP connection'],boundary:'A TV presentation or page label is not an access-control boundary. A deployed system needs approved permissions and a secured shop-floor device.'},
 data:{number:'04',name:'Data access & history',tag:'Board server or device storage',icon:'history',summary:'Structured records → one shared board',detail:'A separate storage layer reads and writes production records. Served by the board server, lead PCs and floor TVs share one board with live updates and a revision check; opened as a file, records stay in that browser. Each update captures a history snapshot including operators, step names, target, stop, gap, hours earned, colour, overtime, and route revision.',fields:['Board server: one shared board, live updates, daily backups','Opened as a file: device-local browser storage','Proposed: ST-approved host and data source; SAP connector in Phase 2','Route revisions keep step names and timings','Supervisor history and trend views','CSV export for review and later analytics'],boundary:'The board server saves the whole board with a revision check and keeps simple backups. Login, record-level concurrent editing, audit retention, and the approved host are for ST IT.'}
};
function renderArchitecture(){const active=architectureLayers[architectureLayer];$('#page-content').innerHTML=`<div class="architecture-status"><span class="hypothesis-badge">ARCHITECTURE HYPOTHESIS</span><p>Working demo modules and proposed deployment boundaries.</p></div><div class="environment-boundary"><div class="environment-heading">${icon('layers')}<div><strong>Proposed ST-approved environment</strong><span>SharePoint or local network · hosting and data location to be validated by ST IT</span></div><span class="boundary-label">INTERNAL BOUNDARY</span></div><div class="architecture-flow">${Object.entries(architectureLayers).map(([key,l])=>`<button class="architecture-node ${key===architectureLayer?'selected':''}" data-layer="${key}" aria-pressed="${key===architectureLayer}"><span class="node-top"><span>${l.number}</span>${icon(l.icon)}</span><strong>${l.name}</strong><p>${l.summary}</p><small>${l.tag}</small></button>`).join('')}</div><div class="architecture-support"><div class="support-card"><span class="support-link">CONFIGURATION → GOAL ENGINE</span><h3>Process definition</h3><p>Named steps · standard minutes · shift budget · colour bands</p><button class="text-button" data-page="process">Open sample process setup ${icon('arrow')}</button></div><div class="support-card"><span class="support-link">STORAGE ↔ BOARD / ANALYTICS</span><h3>Approved shared repository</h3><p>Production records + append-only history proposed. SharePoint, OneDrive, Excel, or local files are candidates to evaluate.</p><span class="proposed-label">Proposed · not connected</span></div></div><div class="flow-caption">Lead input → calculate → validate and store → render board / TV → review history</div></div><div class="architecture-bottom"><section class="layer-detail"><div class="section-top"><h2>${active.number} / ${active.name}</h2><span class="status">${active.tag}</span></div><p>${active.detail}</p><div class="layer-fields">${active.fields.map(f=>`<div>${icon('check')}<span>${f}</span></div>`).join('')}</div><div class="decision-note">${active.boundary}</div></section><aside class="external-boundaries"><h2>Outside this MVP</h2><div>${icon('close')}<span><strong>SAP / ERP / future MPP</strong><small>No direct integration in this prototype</small></span></div><div>${icon('close')}<span><strong>Public internet</strong><small>No runtime dependency; all assets are local</small></span></div><p>Potential future integration requires a separate scope and approval. No manufacturing data is sent to an external service by this application.</p></aside></div><section class="constraints-panel"><h2>Constraints that shape the design</h2><div class="constraint-grid"><div><strong>Union / workforce rules</strong><span>Validate names, history, and permitted comparisons.</span></div><div><strong>GCC High / FedRAMP</strong><span>Validate applicable requirements and approved environment with ST IT.</span></div><div><strong>Proprietary data</strong><span>Fictional records now; approved internal handling later.</span></div><div><strong>User simplicity</strong><span>Short forms, clear states, readable TV output.</span></div><div><strong>Hard to break</strong><span>Controlled fields, calculated targets, stable layouts.</span></div><div><strong>Long-term scalability</strong><span>Process configuration + replaceable storage adapter.</span></div></div></section>`;}
$('#process-filter').addEventListener('change',e=>{selectedProcess=e.target.value;tvPage=0;render();});
$('#job-form').addEventListener('input',e=>{const f=$('#job-form');if(e.target.name==='start'){const start=Number(f.elements.start.value);f.elements.end.innerHTML=stopOptions(window.questEditingSequence.stepNames,start,Math.max(start,Number(f.elements.end.value)));}if(['start','end','overtimeHours','allocationHours','delayHours','operators','date','shift'].includes(e.target.name))updateGoalPreview();});
$('#job-form').addEventListener('invalid',e=>{const section=e.target.closest('details');if(section)section.open=true;},true);
$('#job-form').addEventListener('change',e=>{if(['cell','date','shift'].includes(e.target.name)){const f=$('#job-form');$('#slot-summary').innerHTML=slotText({cell:f.elements.cell.value,date:f.elements.date.value,shift:f.elements.shift.value});}if(e.target.name==='processId'){const p=state.processes.find(p=>p.id===e.target.value),f=$('#job-form');window.questEditingSequence={stepMinutes:[...p.stepMinutes],stepNames:[...p.stepNames],rateMultiplier:p.rateMultiplier,configRevision:p.revision,productiveMinutes:p.productiveMinutes,goalRule:p.goalRule};f.elements.start.innerHTML=startOptions(p.stepNames,0);f.elements.end.innerHTML=stopOptions(p.stepNames,0,0);updateGoalPreview();}});
document.addEventListener('change',e=>{if(e.target.id==='config-process'){selectedProcess=e.target.value;renderProcessChoices();render();}if(e.target.id==='config-step-count'){const count=Number(e.target.value);if(Number.isInteger(count)&&count>=1&&count<=999){const form=$('#process-form'),names=$$('[name="stepName"]',form).map(i=>i.value),minutes=$$('[name="duration"]',form).map(i=>Number(i.value));loadRoute(Array.from({length:count},(_,i)=>names[i]??`Step ${i+1}`),Array.from({length:count},(_,i)=>minutes[i]??45));}}if(e.target.id==='supervisor-weeks'){supervisorWeeks=Number(e.target.value);render();}if(e.target.id==='flag-at'){flagAt=Number(e.target.value);render();}});
document.addEventListener('input',e=>{if(e.target.name==='duration')updateRouteTotals();});
document.addEventListener('submit',e=>{if(e.target.id==='process-form')saveProcess(e);});document.addEventListener('click',e=>{const layer=e.target.closest('[data-layer]');if(layer){architectureLayer=layer.dataset.layer;renderArchitecture();hydrateIcons();}if(e.target.closest('#apply-import'))applyImport();if(e.target.closest('#restore-process'))restoreProcess();});
initWorkflow();renderProcessChoices();renderCellChoices();render();saveState();
// A floor TV opens straight into the display: ?display=tv, optionally &layout=cells|timeline|goals. Controls fade until the mouse moves over them.
{const params=new URLSearchParams(location.search);if(params.get('display')==='tv'){document.body.classList.add('kiosk');toggleTv();if(TV_LAYOUTS.includes(params.get('layout'))){tvLayout=params.get('layout');render();}}}
sync?.connect(state).then(shared=>{if(shared)$('#reset-dialog p').textContent='This restores the fictional sample jobs and history for every screen on this board server.';});
